function detectOs(name: string): OsInfo | null {
  const lower = name.toLowerCase();
  for (const { keys, info } of OS_MAP) {
    if (keys.some(k => lower.includes(k))) return info;
  }
  return null;
}

interface OsLogoProps {
  name: string;
  className?: string;
}

export function OsLogo({ name, className = 'h-8 w-8' }: OsLogoProps) {
  const os = detectOs(name);

  if (!os) {
    return <Monitor className={`${className} text-muted-foreground`} />;
  }

  return (
    <span
      className={`inline-flex items-center justify-center rounded-md ${className}`}
      style={{ backgroundColor: os.bg, color: os.fg, flexShrink: 0 }}
      title={name}
    >
      {os.svg ? (
        <span className="h-5 w-5 flex items-center justify-center">
          {os.svg}
        </span>
      ) : (
        <span className="text-xs font-bold">{os.label}</span>
      )}
    </span>
  );
}
